    public function activate(int $assetId,string $inServiceDate,int $actorId): array
    {$connection=\db();$owns=!$connection->inTransaction();try{if($owns)$connection->beginTransaction();$company=$this->tenant->companyId();$asset=$this->assets->asset($company,$assetId,true);if(!$asset||$asset['status']!=='draft')throw new RuntimeException('Only a company draft asset can be activated.');if(!$this->date($inServiceDate)||$inServiceDate<$asset['acquisition_date'])throw new RuntimeException('In-service date cannot precede acquisition.');$cost=round((float)$asset['acquisition_cost']+(float)$asset['additional_capitalized_cost'],2);$schedule=$this->calculator->schedule($cost,(float)$asset['salvage_value'],(int)$asset['useful_life_months'],$inServiceDate);if(empty($asset['acquisition_journal_batch_id'])){$accounts=$this->finance->ensureSystemAccounts($company,(string)$asset['currency'],$actorId);$journal=$this->finance->postBalancedJournal($company,'ASSET-ACQ-'.$assetId,'asset_acquisition',(string)$assetId,(string)$asset['asset_number'],(string)$asset['acquisition_date'],(string)$asset['currency'],'Direct fixed asset acquisition','asset-acquisition-'.$company.'-'.$assetId,[['account_id'=>(int)$asset['asset_account_id'],'debit'=>$cost,'credit'=>0,'description'=>'Fixed asset acquired'],['account_id'=>$accounts['cash'],'debit'=>0,'credit'=>$cost,'description'=>'Acquisition funding']],$actorId);\db()->prepare('UPDATE fixed_assets SET acquisition_journal_batch_id=:batch WHERE company_id=:company_id AND asset_id=:asset_id')->execute(['batch'=>$journal['journalBatchId'],'company_id'=>$company,'asset_id'=>$assetId]);}$this->assets->activate($company,$assetId,$inServiceDate,$schedule,$actorId);$this->assets->history($company,$assetId,'activated','draft','active',['periods'=>count($schedule)],$actorId);if($owns)$connection->commit();return['successful'=>true,'id'=>$assetId,'periods'=>count($schedule)];}catch(Throwable $e){if($owns&&$connection->inTransaction())$connection->rollBack();return['successful'=>false,'errors'=>['form'=>$e->getMessage()]];}}
    public function postDepreciation(int $lineId,int $actorId): array
