    {$connection=\db();$owns=!$connection->inTransaction();try{if($owns)$connection->beginTransaction();$company=$this->tenant->companyId();$asset=$this->assets->asset($company,$assetId,true);if(!$asset||!in_array($asset['status'],['active','fully_depreciated'],true))throw new RuntimeException('Only an active or fully depreciated asset can be disposed.');$type=(string)($input['disposal_type']??'');$date=(string)($input['disposal_date']??'');$reason=trim((string)($input['reason']??''));$proceeds=round((float)($input['proceeds_amount']??0),2);if(!in_array($type,['sale','scrap','write_off'],true)||!$this->date($date)||$reason===''||$proceeds<0||($type!=='sale'&&$proceeds>0))throw new RuntimeException('Valid disposal type, date, proceeds and reason are required.');$cost=round((float)$asset['acquisition_cost']+(float)$asset['additional_capitalized_cost'],2);$accumulated=round((float)$asset['accumulated_depreciation'],2);$book=round($cost-$accumulated,2);$gain=max(0,round($proceeds-$book,2));$loss=max(0,round($book-$proceeds,2));$accounts=$this->finance->ensureSystemAccounts($company,(string)$asset['currency'],$actorId);$lines=[];if($accumulated>0)$lines[]=['account_id'=>(int)$asset['accumulated_depreciation_account_id'],'debit'=>$accumulated,'credit'=>0,'description'=>'Remove accumulated depreciation'];if($proceeds>0)$lines[]=['account_id'=>$accounts['cash'],'debit'=>$proceeds,'credit'=>0,'description'=>'Asset sale proceeds'];if($loss>0)$lines[]=['account_id'=>(int)$asset['disposal_loss_account_id'],'debit'=>$loss,'credit'=>0,'description'=>'Loss on disposal'];$lines[]=['account_id'=>(int)$asset['asset_account_id'],'debit'=>0,'credit'=>$cost,'description'=>'Remove fixed asset cost'];if($gain>0)$lines[]=['account_id'=>(int)$asset['disposal_gain_account_id'],'debit'=>0,'credit'=>$gain,'description'=>'Gain on disposal'];$journal=$this->finance->postBalancedJournal($company,'DISP-'.$assetId,'asset_disposal',(string)$assetId,(string)$asset['asset_number'],$date,(string)$asset